"""Append optional E1 campaign data without modifying prior quest records."""
from pathlib import Path
import json
r=Path(__file__).resolve().parents[1]
def append(file,record):
 p=r/file;a=json.loads(p.read_text(encoding='utf-8'))
 if not any(x['id']==record['id'] for x in a):a.append(record)
 p.write_text(json.dumps(a,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
append('assets/kingdom/buildings.json',dict(id='marketplace',name=['Lantern Marketplace','Fener Pazarı'],description=['Assign merchants to buy, sell and send real caravans.','Alım, satım ve gerçek kervanlar için tüccar ata.'],level=21,cost=dict(wood=16,stone=8,gold=3),ticks=6,slots=2,output='',role=['Merchant','Tüccar'],site='land',limit=1))
append('assets/kingdom/quests.json',dict(id='main_21',level=21,chapter=5,title=['The First Trade Road','İlk Ticaret Yolu'],description=['A road joins your kingdom to distant traders. Build a market, compare prices, and bring an actual caravan home.','Bir yol krallığını uzak tüccarlara bağlar. Pazar kur, fiyatları karşılaştır ve gerçek kervanı eve getir.'],tracking='realm_lifetime',prerequisites=['main_20'],objectives=[dict(kind=k,key=key,target=1,text=text,navigate=nav) for k,key,text,nav in [('building','marketplace',['Build a marketplace','Pazaryeri inşa et'],'build_marketplace'),('trade','merchant',['Assign a merchant','Tüccar ata'],'workers'),('trade','prices',['Inspect regional prices','Bölgesel fiyatları incele'],'trade'),('trade','delivered',['Collect a returned delivery','Dönen teslimatı al'],'trade')]],rewards=dict(xp=840,wood=8,stone=4,gold=4),next=''))
art=r/'assets/kingdom'
